+  account._jid = { node: NICK };
+  account._mucService = MUC_SERVICE;
+
+  const result = account.getChatRoomDefaultFieldValues();
+  Assert.deepEqual(
+    result.values,
+    { server: MUC_SERVICE, nick: NICK },
+    "Unexpected default values"
+  );
+});
